import{_ as d,o as a,c as r,ai as e}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"AI 热门软件与开源项目地图","description":"","frontmatter":{},"headers":[],"relativePath":"ai/explore/index.md","filePath":"ai/explore/index.md"}'),o={name:"ai/explore/index.md"};function n(h,t,i,l,s,g){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-热门软件与开源项目地图" tabindex="-1">AI 热门软件与开源项目地图 <a class="header-anchor" href="#ai-热门软件与开源项目地图" aria-label="Permalink to “AI 热门软件与开源项目地图”">​</a></h1><blockquote><p><strong>定位</strong>：用一张「分类地图」快速了解当下常见的 AI 应用、工具与开源项目——适合 <strong>选型参考、按需学习、面试闲聊素材</strong>，不等同于官方排行榜。<br><strong>和维护关系</strong>：仓库迭代快，请以各项目官网 / Release 为准；本文只描述<strong>典型用途</strong>与<strong>学习优先级</strong>。</p></blockquote><hr><h2 id="这张地图怎么读" tabindex="-1">这张地图怎么读？ <a class="header-anchor" href="#这张地图怎么读" aria-label="Permalink to “这张地图怎么读？”">​</a></h2><table tabindex="0"><thead><tr><th>你的目标</th><th>建议优先看</th></tr></thead><tbody><tr><td>先把大模型用顺、提效开发</td><td><a href="#一对话与编程辅助商用-开源">对话与编程辅助</a>、本地轻量 <a href="#二本地推理与管理终端侧体验">本地推理</a></td></tr><tr><td>做 Agent / 自动化工作流</td><td><a href="#三agent-工作流编排">Agent 与可视化编排</a>、<a href="#四rag-记忆-知识库">RAG 与知识库</a></td></tr><tr><td>自己部署模型、省 API 钱</td><td><a href="#五训练推理与服务化-gpu-工程向">推理与服务化</a></td></tr><tr><td>多模态 / AIGC 玩图与视频</td><td><a href="#六多模态与-aigc-管线">多模态与创意管线</a></td></tr><tr><td>了解「业界在造什么轮子」</td><td>全文扫一遍，把感兴趣的 <strong>Star + 读 README</strong></td></tr></tbody></table><hr><h2 id="一、对话与编程辅助-商用-开源" tabindex="-1">一、对话与编程辅助（商用 + 开源） <a class="header-anchor" href="#一、对话与编程辅助-商用-开源" aria-label="Permalink to “一、对话与编程辅助（商用 + 开源）”">​</a></h2><p>面向<strong>日常提问、写代码、改文档</strong>：闭源产品体验通常更省心；开源类适合<strong>自建、二次开发、学习协议与插件</strong>。</p><table tabindex="0"><thead><tr><th>名称</th><th>形态</th><th>适合谁</th><th>一句话</th><th>入口</th></tr></thead><tbody><tr><td>ChatGPT / Copilot（微软）</td><td>商用订阅</td><td>全栈、办公提效</td><td>生态全、插件多，适合「先习惯 AI 结对编程」</td><td>官网各产品线</td></tr><tr><td>Claude</td><td>商用 API / 网页</td><td>长文本、复杂推理</td><td>长上下文与说明书类任务口碑好</td><td>Anthropic</td></tr><tr><td>Cursor</td><td>商用 IDE</td><td>前端/全栈</td><td>「AI 原生编辑器」代表，适合重度编码</td><td>cursor.com</td></tr><tr><td>Continue</td><td>开源插件</td><td>想用 VS Code / JetBrains + 自建模型</td><td>可对接本地/Ollama/云端，适合练「工具链组装」</td><td>GitHub: continue-dev/continue</td></tr><tr><td>GitHub Copilot</td><td>商用</td><td>已在 Git GitHub 生态内</td><td>与 PR、Issue、Copilot Chat 一体</td><td>GitHub</td></tr><tr><td>通义灵码 / 豆包 / Kimi 等</td><td>国产商用</td><td>国内网络与合规</td><td>中文场景与文档检索往往更顺手</td><td>各厂商官网</td></tr></tbody></table><p><strong>学习建议</strong>：至少熟练 <strong>1 个闭源对话</strong> + <strong>1 个编辑器内助手</strong>；有折腾精神再装 <strong>Continue + 本地模型</strong>。</p><hr><h2 id="二、本地推理与管理-终端侧体验" tabindex="-1">二、本地推理与管理（终端侧体验） <a class="header-anchor" href="#二、本地推理与管理-终端侧体验" aria-label="Permalink to “二、本地推理与管理（终端侧体验）”">​</a></h2><p>在<strong>本机或内网</strong>跑小模型：隐私、离线、省 token；代价是机器配置与工程排错。</p><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>适合谁</th><th>一句话</th><th>入口</th></tr></thead><tbody><tr><td>Ollama</td><td>本地模型拉起 + CLI</td><td>入门本地推理首选</td><td><code>pull / run</code> 一条龙，和 Continue、Dify 等常联动</td><td>ollama.com</td></tr><tr><td>llama.cpp</td><td>C/C++ 推理引擎</td><td>要极致压缩与嵌入式</td><td>各类「.gguf」与边缘部署常见底座</td><td>ggerganov/llama.cpp</td></tr><tr><td>LM Studio</td><td>桌面 GUI</td><td>不想敲命令</td><td>可视化下载与聊天，适合非研发体验</td><td>lmstudio.ai</td></tr><tr><td>llamafile</td><td>单文件分发</td><td>演示与传播</td><td>把权重+运行时打成一个文件，便于分享</td><td>Mozilla Ocho 系</td></tr><tr><td>GPT4All</td><td>桌面 + 本地 RAG</td><td>轻量知识库试验</td><td>自带简单文档检索玩法的入门套件</td><td>nomic-ai/gpt4all</td></tr></tbody></table><hr><h2 id="三、agent-工作流编排" tabindex="-1">三、Agent / 工作流编排 <a class="header-anchor" href="#三、agent-工作流编排" aria-label="Permalink to “三、Agent / 工作流编排”">​</a></h2>',16)])])}const b=d(o,[["render",n]]);export{p as __pageData,b as default};
